ProjectALife.DialogueShards["replies_ask_15"] = {
{"ASK_LOOT_SPOT","role=family_man,family_woman,family_youth|tmp=fresh,seasoned|st=friendly,neutral",{"Houses on the north side haven't been checked, we took what we could carry"}},
{"ASK_LOOT_SPOT","role=family_man,family_woman,family_youth|tmp=fresh,seasoned|st=friendly,neutral|world=building",{"The elementary school pantry, we got half of it before the others came"}},
{"ASK_LOOT_SPOT","role=civilian_man,civilian_woman|tmp=fresh,seasoned|st=friendly,neutral",{"The Johnson house on Elm, they left in a hurry and left the cupboards stocked","Hardware store on Main, everybody hit the front - nobody checked the back"}},
{"ASK_LOOT_SPOT","role=civilian_man,civilian_woman|tmp=fresh,seasoned|st=careful",{"Find your own - we have"}},
{"ASK_LOOT_SPOT","role=civilian_loner|tmp=seasoned|st=friendly,neutral",{"Hunting cabins up the ridge, nobody thinks to look there","Old farmsteads - Cellars, preserved food goes a long way"}},
{"ASK_LOOT_SPOT","role=worker|tmp=seasoned|st=friendly,neutral",{"The plant's break room, vending machines, still full - it's a long walk","Auto shop on 31W, tools, batteries, a little of everything"}},
{"ASK_LOOT_SPOT","role=rescue_firefighter|tmp=seasoned|st=friendly,neutral",{"Gas stations have bottled water in the back - check the cooler"}},
{"ASK_LOOT_SPOT","role=rescue_firefighter|tmp=seasoned|st=friendly,neutral|world=building",{"Station houses, every firehouse has a kitchen, and nobody remembers that"}},
{"ASK_LOOT_SPOT","role=rescue_medical|tmp=seasoned|st=friendly,neutral",{"Veterinary clinics, nobody looks there, and they keep antibiotics and bandages","School nurse offices, small and overlooked - usually stocked"}},
{"ASK_LOOT_SPOT","role=rescue_clergy|tmp=seasoned|st=friendly,neutral|world=building",{"Churches keep canned goods in the basement for charity, we took a share - take a share"}},
{"ASK_LOOT_SPOT","role=rescue_clergy|tmp=seasoned|st=friendly,neutral",{"The rectory on St. Mark's - nobody's home, I left the key under the mat"}},
{"ASK_LOOT_SPOT","role=law_deputy,law_officer|tmp=seasoned|st=friendly,neutral",{"The county garage on Pike, locked, but I've got the combination - don't broadcast it"}},
{"ASK_LOOT_SPOT","role=law_deputy,law_officer|tmp=seasoned|st=friendly,neutral|world=door",{"Hardware store on Main - don't force the door, there's a key in the lockbox out front"}},
{"ASK_LOOT_SPOT","role=law_deputy,law_officer|tmp=seasoned|st=careful",{"I'm not a tour guide for looters"}},
{"ASK_LOOT_SPOT","role=law_sheriff,law_sergeant|tmp=veteran|st=friendly,neutral",{"I can't approve of looting, but the school cafeteria is unattended"}},
{"ASK_LOOT_SPOT","role=law_sheriff,law_sergeant|tmp=veteran|st=careful",{"If I told you, I'd have to arrest you - move on"}},
{"ASK_LOOT_SPOT","role=law_trooper|tmp=veteran|st=friendly,neutral|world=vehicle",{"Truck stops - Cabs sit full of food and nobody checks them"}},
{"ASK_LOOT_SPOT","role=law_trooper|tmp=veteran|st=friendly,neutral|world=cars",{"Abandoned cars on the interstate, glove boxes, trunks - take your time"}},
{"ASK_LOOT_SPOT","role=law_corrections|tmp=seasoned|st=friendly,neutral",{"Jail commissary's still stocked, but the key stays with me"}},
{"ASK_LOOT_SPOT","role=law_corrections|tmp=seasoned|st=careful",{"I'm not a supply clerk"}},
{"ASK_LOOT_SPOT","role=swat_lead,swat_operator|tmp=veteran|st=friendly,neutral",{"Armory at the sheriff's office - don't bother, we emptied it"}},
{"ASK_LOOT_SPOT","role=swat_lead,swat_operator|tmp=veteran|st=careful",{"Find your own cache"}},
{"ASK_LOOT_SPOT","role=soldier,soldier_green|tmp=seasoned,fresh|st=friendly,neutral",{"Supply depots are picked clean - try the little places nobody listed"}},
{"ASK_LOOT_SPOT","role=soldier,soldier_green|tmp=seasoned,fresh|st=careful",{"Can't point you anywhere"}},
{"ASK_LOOT_SPOT","role=soldier_nco|tmp=veteran|st=friendly,neutral",{"The empty barracks on the east side - Footlockers, most of them - don't touch the ammo"}},
{"ASK_LOOT_SPOT","role=soldier_nco|tmp=veteran|st=careful",{"I won't tell you - move out"}},
{"ASK_LOOT_SPOT","role=deserter,militia|tmp=seasoned|st=friendly,neutral",{"Abandoned guard posts, they left rations behind"}},
{"ASK_LOOT_SPOT","role=deserter,militia|tmp=seasoned|st=careful",{"Not telling"}},
{"ASK_LOOT_SPOT","role=elite_operator,elite_delta,mercenary|tmp=veteran|st=friendly,neutral|world=door",{"One-door buildings with no sign, big targets get hit first"}},
{"ASK_LOOT_SPOT","role=elite_operator,elite_delta,mercenary|tmp=veteran|st=careful",{"No"}},
{"ASK_LOOT_SPOT","role=outlaw|tmp=seasoned|st=friendly,neutral",{"Check the farms off Highway 31, people left in a hurry","Convenience stores in the back country - easy pickings, still"}},
{"ASK_LOOT_SPOT","role=outlaw|tmp=seasoned|st=careful",{"Why share? You think I'm stupid?"}},
{"ASK_LOOT_SPOT","role=raider,raider_boss|tmp=predator|st=friendly,neutral",{"Look around, everybody's got something - take it"}},
{"ASK_LOOT_SPOT","role=raider,raider_boss|tmp=predator|st=friendly,neutral|world=water",{"The houses along the river have boats and canned goods - and a few dead owners"}},
{"ASK_LOOT_SPOT","role=raider,raider_boss|tmp=predator|st=careful",{"Find your own score"}},
{"ASK_LOOT_SPOT","role=gang_member,gang_boss|tmp=predator|st=friendly,neutral",{"Check the liquor store on the corner, some bottles survived","The empty tenement on 4th Street, folks left cans"}},
{"ASK_LOOT_SPOT","role=gang_member,gang_boss|tmp=predator|st=careful",{"Find your own"}},
{"ASK_LOOT_SPOT","role=biker,biker_boss|tmp=predator,veteran|st=friendly,neutral|world=road",{"The roadside diner on the county line - back freezer was untouched"}},
{"ASK_LOOT_SPOT","role=biker,biker_boss|tmp=predator,veteran|st=friendly,neutral|world=vehicle,building",{"Truck stops, every one has a pantry"}},
{"ASK_LOOT_SPOT","role=biker,biker_boss|tmp=predator,veteran|st=careful",{"We hit it first"}},
{"ASK_LOOT_SPOT","role=crime_member|tmp=seasoned|st=friendly,neutral",{"The warehouse on the south side, it's locked, but I know a man with a key - price applies"}},
{"ASK_LOOT_SPOT","role=crime_member|tmp=seasoned|st=careful",{"Info costs, friend"}},
{"ASK_LOOT_SPOT","role=prisoner|tmp=predator|st=friendly,neutral|world=road",{"The state road gas station - back room - don't let anyone see you"}},
{"ASK_LOOT_SPOT","role=prisoner|tmp=predator|st=friendly,neutral|world=door",{"Houses with the doors left open - nobody's home"}},
{"ASK_LOOT_SPOT","role=prisoner|tmp=predator|st=careful",{"Not telling a guard's cousin where to find things"}},
{"ASK_LOOT_SPOT","role=civilian_man,civilian_woman|tmp=fresh|st=friendly,neutral",{"Houses! the ones nobody's touched, the ones with drawn curtains, but, uh, bring a bat, just in case","Pantries... cupboards, under sinks, people hide the good stuff in boring places","Pharmacies, but they've been hit, so try the back rooms, the stockrooms, the places people forget","Garages... toolboxes, workshops, you'd be amazed what people leave in a garage","Check the nightstands -- medicine cabinets, the junk drawers, it all adds up","I don't know, I just kinda wander, and sometimes I get lucky, most times I don't!","Churches have food drives... boxes of canned goods in the basement, I got a whole case once","Schools have cafeterias, big freezers, though the freezers are gone by now, pantries aren't"}},
{"ASK_LOOT_SPOT","role=civilian_man,civilian_woman|tmp=seasoned|st=friendly,neutral",{"Everywhere's been looted, so look where people stopped looking, the high shelves, the back rooms","Houses on the edge of town, they were last to be hit, some have gardens still","Crawl spaces... attics, cellars, folks hid stuff in 'em, it's old-fashioned, it works","Farms, outbuildings, sheds, seed, feed, canned goods, even tools","Check anything with a lock, the locked places are the least picked","The newer the house, the emptier it is, the old farmhouses still have stores","Funeral homes, I'm not joking, they've got caskets and cold rooms and, oddly, coffee"}},
{"ASK_LOOT_SPOT","role=civilian_man,civilian_woman|st=friendly",{"For you, there's a place I haven't been brave enough to try, but you might be!","I've got a list, and I'd give you half, you'd be doing me a favor, I don't like going alone","There's a good spot I know, I'll tell you if you come back and tell me what you found"}},
{"ASK_LOOT_SPOT","role=civilian_man,civilian_woman|st=careful",{"If I knew, I wouldn't tell you","You wanna rob my spot? no thanks","Find your own, I found MINE, so can you","Not telling, don't push it"}},
{"ASK_LOOT_SPOT","role=civilian_loner",{"Every house has something if you've got a crowbar and nowhere to be","Hunting cabins, they're stocked for winter, nobody remembers them, and the doors are weak","Back of a barn, behind the hay, folks hide jars and tins there, I've found money too","Cabins down by the lake, folks left ice chests, fishing gear, even coffee once","Roadside stands, motels, truck stops, but they're picked clean, so you'll have to go deeper..","Look for the places that smell wrong, the smell scares the scavengers, and I don't mind it","Any building where the door's been forced, somebody already took the easy stuff, so look for the hard stuff"}},
{"ASK_LOOT_SPOT","role=civilian_loner|st=careful",{"My spots are MINE","I don't do directions!","Look for yourself","If I tell you, you'll go, then the next fella follows you - so, no"}},
{"ASK_LOOT_SPOT","role=family_man,family_woman,family_elder,family_youth|st=friendly,neutral",{"We found a whole pantry at a church, they'd stocked up for the winter, we took only half, we left the rest","Houses with kids' rooms, there's usually cookies, or juice boxes, or something sweet","Check under beds, behind the water heater, inside the oven, people hide cash and canned goods","Basements! old houses, root cellars, jars of preserves, you won't believe what's down there"}},
{"ASK_LOOT_SPOT","role=family_elder",{"My late husband's workshop has nails, screws, rope, wire, if you can pry the door","The church kitchen, the Ladies Auxiliary stored coffee and sugar, enough for a hundred suppers","Everybody's attic, honey, everybody's got an attic, and nobody ever cleans it"}},
{"ASK_LOOT_SPOT","role=family_youth",{"School vending machines, I know, they've been robbed, but the back ones, the teachers' lounge, nobody checks","Houses, I guess? I don't know, I just grab whatever I can","Check bedrooms, kids hide candy in their closets, I know because I do too"}},
{"ASK_LOOT_SPOT","role=worker",{"Shops, the plant, any warehouse, there's first aid kits and rope and a whole stockroom sometimes","Loading docks, back offices, break rooms, the vending machines and the fridge","Lockers, desks, toolboxes, folks leave lunch in 'em, sometimes a pistol","Hardware stores go first, so try the lumber yards, the fence suppliers, the places nobody thinks about"}},
{"ASK_LOOT_SPOT","role=rescue_medical",{"Pharmacies, doctors' offices, vet clinics, you'd be surprised what vets have...","Nursing homes, if you can stomach it, they keep a lot of supplies, and a lot of other things","Dental offices... they have lidocaine, they have sterile instruments, don't laugh, they do.."}},
{"ASK_LOOT_SPOT","role=rescue_clergy",{"Parish halls have kitchens, kitchens have flour, and flour has been my savior","There's a food bank in the basement, but we've emptied it, check the neighboring parishes"}},
{"ASK_LOOT_SPOT","role=rescue_firefighter",{"Fire stations have first aid, flashlights, hoses, ropes, but we've stripped ours","Schools have medical supplies, a nurse's office with bandages and ice packs","Camping stores, hardware stores, check the back for the heavy stuff, tents, tarps, tools"}},
{"ASK_LOOT_SPOT","role=militia",{"Armories, gun shops, pawn shops, hardware stores, all of them hit, but sometimes there's a safe","Check the sheds behind the farms, the old men kept their rifles there, and a lot of ammo","Outbuildings, hunting cabins, tool sheds, that's where I'd start"}},
{"ASK_LOOT_SPOT","reg=civilian,family,worker,rescue|st=friendly,neutral|rep=good,best",{"Check around the back rooms first, you've been a friend, you deserve a break","There's a spot I've saved for someone I trust, and that someone is you","Here's a secret, I found a stash, I'll tell you where, but share it with me, deal?","Try the stockroom behind a pharmacy, the back shelves, hardly touched","Try the hunting cabins up the ridge, nobody remembers them, there's canned goods and blankets","The church basement on the far side of town, they stored a winter's worth, it's open to those who need it","There's a farm with a root cellar, past the second bridge, the family left in a hurry, they won't mind","The school nurse's office, bottom drawer, bandages and aspirin, I checked yesterday!","I found a case of soup in a garage, a couple of streets over, and I left half for the next person","Check inside the feed store, behind the seed bags, there's a locked cabinet","Any tool shed out back of a house, rope, wire, a good axe, the owners don't need them now","Behind the barbershop, a storeroom, towels, soap, razors, candles","Find a house with a real pantry, I only took a little from mine, you take what you need","The old gas station, in the back, a cooler of bottled water, still sealed","Check the junk drawers, I found matches and gum in one, you never know!","I know a bakery with flour sacks stacked in the back, still dry, still good","Take what you need from the shop on the corner, the owner told me before he left","Try the library basement, books burn, so there's wood, and cans from the staff kitchen!","Don't forget the attics, people hide things in attics, I found a box of canned peaches!","The funeral home has a lot of supplies, tidy, locked, but I know a window","I can't promise it's full -- but the old hardware store has some","Hit the houses with the drawn blinds -- nobody's been in!!","There's a little grocery out by the lake, I'd take it, but I can't carry it all","The VFW hall stocked up for a hunting dinner, forty pounds of beans in the pantry","Check the trailers behind the lot, they're easy to forget","A fire station's pantry is probably untouched, nobody thinks to look","A bunch of canned goods in the basement of the old bank, don't ask how!","There's a cabin by the water, full of fishing gear, hooks, line, a net","The dentist's office has surprisingly good first aid, the dentist was a tidy man","Try the car dealership's break room, snacks, coffee, a coat rack of jackets","The old mill's storeroom, but only in daylight, and bring a friend","I keep a stash -- you can borrow from it, just leave a note","There's a place I'm saving, just in case, for you, if you ever need it"}},
{"ASK_LOOT_SPOT","reg=civilian,family,worker,rescue|st=friendly,neutral|rep=bad,worst",{"If I KNEW a good spot, I'd keep it from you","Nothing, and don't ask me again"}},
{"ASK_LOOT_SPOT","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly,neutral|mood=fear",{"I can't tell you a good place. I'd be afraid to send you somewhere I haven't checked","The houses on the end, but be quiet, be so quiet, please, I heard something in the last one","I found canned food in a basement once, I had to crawl over- never mind, I don't want to say","Anywhere... everywhere -- nowhere, I don't know, I eat what I find, and I run"}},
{"ASK_LOOT_SPOT","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral|mood=grim",{"Wherever people lived and died quickly, they left the best behind","Ignore the obvious places, the obvious places are bare, go for the odd ones","A house with the curtains drawn and a bad smell, that's usually untouched"}},
{"ASK_LOOT_SPOT","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=sad",{"My own house, the pantry, I couldn't bring myself to go back... but it's full... go ahead... take what you need","Missus Allen's kitchen, she kept so many jars... I think about them... I think about her"}},
{"ASK_LOOT_SPOT","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=angry",{"They've picked it all clean, the vultures, every shelf, every drawer, every crumb","Wherever you look, someone got there first, and left the mess, the bastards"}},
{"ASK_LOOT_SPOT","reg=civilian,family,worker,rescue|st=friendly|mood=warm",{"I've got a map, I marked the good ones, copies are hard to come by, though","There's a place I saved for a friend, and I'd like it to be you"}},
{"ASK_LOOT_SPOT","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=funny",{"My secret spot? The back of my mother-in-law's closet, it's full of fruitcake, you're welcome","Oh, try anywhere that says \"no trespassing,\" those are always the best!","Everywhere but the places you already looked","Under the couch cushions","My grandmother's purse","The couch cushions"},false,false,{[3]={{t="that's my rule",afterMs=3000},{t="it hasn't worked yet",afterMs=2800}},[4]={{t="I once found three dollars and a very old jelly bean... heh",afterMs=3000}},[5]={{t="bottomless, and terrifying",afterMs=3200}},[6]={{t="we found a dollar and a fossilized french fry",afterMs=3000}}}},
{"ASK_LOOT_SPOT","reg=civilian,family,worker,rescue|st=careful|mood=fear",{"Find your own, don't follow me","Not telling, those spots are MINE"}},
{"ASK_LOOT_SPOT","role=rescue_medical|st=friendly,neutral",{"Pharmacies have been picked clean, but veterinary clinics, dental offices, school nurse stations, they're overlooked","Look for anything marked \"first aid,\" any cabinet with a red cross, and don't skip the bathrooms","Drugstores' back rooms... the shelves behind the pharmacist, people forget they're there","Nursing homes keep gloves, gowns, bleach, saline, if you can stomach the walk","School nurse offices, it ain't a hospital, but nobody's looted a school nurse"}},
{"ASK_LOOT_SPOT","role=rescue_medical|st=careful",{"My supplies are for my patients, NOT for browsing"}},
{"ASK_LOOT_SPOT","reg=civilian,family,worker,rescue|st=careful,neutral|rep=bad,worst",{"Loot? There's NOTHING for you","Find it yourself, thief","I wouldn't tell you where to find a puddle!","Looting is what people like you do","Nope, nothing, go away","Everything's been taken, probably by you","Check your own pockets","I'll never tell","Look where you've already been","Walk in circles, maybe you'll trip over something","Try the next county","No supplies -- no stash, no secrets, not for you","Your reputation precedes you, and I'm not helping","Go ahead and search, you'll find only disappointment","I know where everything is, and I'm not saying","Would you share if I asked?","Go on, ask someone who trusts you","You'll NEVER get anything from me","Ask your friends, if you have any","I'd rather burn it than give it to you","Don't count on me to feed your habits","Help yourself, as you always do","I won't be your supplier","There's nothing left, and if there was, it's not for you","Go find your own, I did","The only thing you'll get from me is directions to leave","You know what you've done, so don't ask!","I'm NOT a charity -- and you're not a cause","Ha! Look who needs a favor","Rummage on your own time"}},
{"ASK_LOOT_SPOT","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|fact=recent_zombie_contact",{"Loot? Are you kidding? with THOSE out there?","Not now, not now, later, when it's safe","Anywhere but HERE, here is no good!","If you can't see the dead... search THERE, but not now","Hush, hush, they're close, we can search in a minute","Right now the only loot is your life... don't lose it!"}},
{"ASK_LOOT_SPOT","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|fact=player_armed",{"With that, you can clear a house, then search it, one room at a time..."}},
{"ASK_LOOT_SPOT","reg=civilian,family,worker,rescue|st=friendly,neutral",{"Try the places people wouldn't think to check","The houses with a lot of kids' bikes in the yard","Under the beds","Church kitchens","Barns...","The back of any closet","Check the garages","Look for the ones that already look picked over","Basements","Abandoned shops","Attics","Laundry rooms","Medicine cabinets, always","Kitchens","Anywhere with a lot of pets","Tackle boxes...","Toolboxes","School lockers","Sewing baskets","Try churches' coat closets","Old folks' houses","Bathroom cabinets","Shed floors","Kitchen drawers, the junk one","A mailbox","The barn rafters...","Under the porch, behind the lattice","Check the pockets of coats","Hunting stands","Tackle boxes in the garage","School desks","Wherever the last one was empty"},false,false,{[1]={{t="hunting cabins, tool sheds, storm cellars",afterMs=3200}},[2]={{t="there's always something in the pantry...",afterMs=3500},{t="cookies, usually",afterMs=3000}},[3]={{t="people hide money and guns and, sometimes, cans",afterMs=3000}},[4]={{t="those church ladies stock for a siege",afterMs=3200}},[5]={{t="feed, tools, sometimes whiskey",afterMs=3000}},[6]={{t="coats, boots, and occasionally treasure",afterMs=3200}},[7]={{t="old men hoard",afterMs=3500}},[8]={{t="folks stop looking, and miss things..",afterMs=3200}},[9]={{t="canned goods, freezers, tools",afterMs=3000}},[10]={{t="the back rooms, not the shelves",afterMs=3500}},[11]={{t="bring a flashlight, and a strong stomach",afterMs=3200}},[12]={{t="soap, bleach, hangers, you'd be surprised",afterMs=3200}},[13]={{t="even the ones that look empty",afterMs=3500}},[14]={{t="the bottom drawer, the pantry, the top of the fridge",afterMs=3000}},[15]={{t="pet food is people food, in a pinch",afterMs=3200}},[16]={{t="hooks, line, knives, sometimes beer",afterMs=3200}},[17]={{t="screwdrivers, pliers, duct tape, the holy trinity",afterMs=3000}},[18]={{t="you'd be amazed what kids hide",afterMs=3500}},[19]={{t="needles, thread, scissors, all useful",afterMs=3200}},[20]={{t="umbrellas, jackets, sometimes a bag of mints",afterMs=3200},{t="you'd be surprised what's useful",afterMs=2800}},[21]={{t="their cupboards are deep, and so are their drawers",afterMs=3500},{t="I feel awful saying so",afterMs=3000}},[22]={{t="aspirin, bandages, razors",afterMs=3200},{t="people always forget the bathroom",afterMs=2800}},[23]={{t="lift the boards, folks hide things",afterMs=3500},{t="a coffee can of screws, once, with a roll of cash",afterMs=3000}},[24]={{t="rubber bands, batteries, matches, string",afterMs=3200}},[25]={{t="the real ones, not the ones on the street",afterMs=3500},{t="I once found a box of crackers in one...",afterMs=3000}},[26]={{t="people throw things up there and forget",afterMs=3200}},[27]={{t="canning jars, sometimes whiskey",afterMs=3500}},[28]={{t="every one, every coat, every pocket",afterMs=3200}},[29]={{t="there's a thermos, a candy bar, a deck of cards, sometimes a flask",afterMs=3500}},[30]={{t="hooks, line, a knife, sometimes a sandwich bag of tobacco",afterMs=3200}},[31]={{t="kids keep gum, change, notes",afterMs=3500},{t="don't read the notes",afterMs=3000}},[32]={{t="folks stop checking, and you shouldn't",afterMs=3200}}}},
{"ASK_LOOT_SPOT","reg=civilian,family,worker,rescue|st=friendly",{"I'll share a trick: go during the day, go slow, and go with a friend","I'll tell you my secret place -- once you promise to share the finds"},false,false,{[1]={{t="preferably me",afterMs=3200}}}},
{"ASK_LOOT_SPOT","reg=civilian,family,worker,rescue|st=careful",{"Why should I tell you where I find things?","Do your own scavenging!","I don't give out spots","If I told you, I'd have competition","Why would I tell a stranger?","There's nothing to find","Look harder","You can find your own"},false,false,{[3]={{t="find your own",afterMs=3000}},[6]={{t="move along",afterMs=3000}}}},
