{"ASK_LOOT_SPOT","role=family_man,family_woman|st=friendly,neutral",{"Houses with swing sets","Kitchen cupboards","Children's rooms"},false,false,{[1]={{t="there's usually a pantry",afterMs=3500}},[2]={{t="people hide candy",afterMs=3200}},[3]={{t="juice boxes, crackers, sometimes a flashlight",afterMs=3500}}}},
